) COMMENT 'Merged product from aviation.inspection_report, row.inspection_report';

CREATE OR REPLACE TABLE `feip_eastus_03`.`aviation`.`safety_plan_document` (
    `safety_plan_document_id` STRING COMMENT 'Primary key for safety_plan_document',
    CONSTRAINT pk_safety_plan_document PRIMARY KEY(`safety_plan_document_id`)
) COMMENT 'Merged product from aviation.safety_plan_document, traffic.safety_plan_document';